@Test
  public void theValue50InTheOldRangeMustBe0_5OnTheNewRange(){
    int fromMin = 0;
    int fromMax = 100;
    int toMin = 0;
    int toMax = 1;

    float result = RangeUtils.getFloatValueInRange(fromMin, fromMax, toMin, toMax, 50);

    Assert.assertTrue(result == 0.5f);
  }

